def addfit(R,g1,g2,n1=113,n2=113):
    # least squares additive model R ~ mu + a[g1] + b[g2]
    # use iterative (alternating) fit
    mu=R.mean(0); A=np.zeros((n1,R.shape[1])); Bv=np.zeros((n2,R.shape[1]))
    for _ in range(20):
        RA=R-mu-Bv[g2]
        for k in range(n1): A[k]=RA[g1==k].mean(0)
        RB=R-mu-A[g1]
        for k in range(n2): Bv[k]=RB[g2==k].mean(0)
    pred=mu+A[g1]+Bv[g2]
    return pred, 1-((R-pred)**2).sum()/((R-R.mean(0))**2).sum()
